/* file : FilesMapper.xml, id : getDtMetaFileList */
SELECT *
FROM TB_META_MODEL_FILES
WHERE DEL_YN = 'N'
  AND REF_TP = #{refType}
  AND MODEL_SEQ = #{refSrno}

/* file : FilesMapper.xml, id : getDtFile */
SELECT *
FROM TB_META_MODEL_FILES
WHERE DEL_YN = 'N'
  AND FILE_SEQ = #{fileSeq}

mapper.insert:
/* file : FilesMapper.xml, id : insertDtFile */
INSERT
INTO TB_MODEL_FILES (
FILE_SEQ
, MODEL_SEQ
, REF_TP
, FILE_NM
, FILE_PATH
, FILE_EXTN
, FILE_SZ
, FILE_CONTS_TP
, REG_USER_SEQ
, REG_IP
)
VALUES (
#{fileSeq}
, #{refSeq}
, #{refTp}
, #{fileNm}
, #{filePath}
, #{fileExtn}
, #{fileSz}
, #{fileContsTp}
, #{loginUserSeq}
, #{loginUserIp}
)

    SELECT LAST_INSERT_ID()

/* file : FilesMapper.xml, id : insertFile */
INSERT
INTO TB_BOARD_FILES ( REF_TP
                    , REF_SEQ
                    , FILE_TP
                    , FILE_NM
                    , FILE_TITLE
                    , FILE_PATH
                    , FILE_EXTN
                    , FILE_SZ
                    , FILE_CONTS_TP
                    , REG_USER_SEQ
                    , REG_IP)
VALUES ( #{refTp}
       , #{refSeq}
       , #{fileTp}
       , #{fileNm}
       , #{fileTitle}
       , #{filePath}
       , #{fileExtn}
       , #{fileSz}
       , #{fileContsTp}
       , #{loginUserSeq}
       , #{loginUserIp})

mapper.update:
/* file : FilesMapper.xml, id : updateFile */
UPDATE TB_BOARD_FILES
SET FILE_PATH     = #{filePath}
  , FILE_CONTS_TP = #{fileContsTp}
  , STRG_FILE_NM  = #{strgFileNm}
  , THUMB_S       = #{thumbS}
  , THUMB_M       = #{thumbM}
  , THUMB_L       = #{thumbL}
WHERE FILE_SEQ = #{fileSeq}

